function githubUrl(skill) {
  if (!DATA.repoBase) return "";
  return `${DATA.repoBase}/tree/main/skills/${skill.slug}`;
}

function assetHref(path) {
  if (!path) return "";
  return path.replace(/^\.\.\//, "../../");
}

function renderTags() {
  els.tags.innerHTML = DATA.teammate.bestFor.map((tag) => `<span class="pill">${tag}</span>`).join("");
}

function renderDirectorDesk() {
  if (!els.directorDesk || !DATA.directorDesk?.length) return;
  els.directorDesk.innerHTML = DATA.directorDesk.map((item) => `
    <div class="detail-box">
      <span>${item.title}</span>
      <strong>${item.body}</strong>
    </div>
  `).join("");
}

function renderDirectorRoutes() {
  if (!els.directorRoutes || !DATA.directorRoutes?.length) return;
  els.directorRoutes.innerHTML = DATA.directorRoutes.map((item) => `
    <article class="featured-card">
      <span class="card-kicker">${item.kicker}</span>
      <h3>${item.title}</h3>
      <div class="teammate-mini" style="--teammate: ${item.color}">
        <span class="teammate-avatar small">${item.avatar}</span>
        <span>
          <strong>${item.name} · ${item.titleRole}</strong>
          <span>${item.personality}</span>
        </span>
      </div>
      <p class="signal">${item.summary}</p>
      <div class="metric-strip">
        ${(item.metrics || []).map((metric) => `<span class="metric-chip">${metric}</span>`).join("")}
      </div>
      <div class="value-tags">
        ${(item.outputs || []).map((output) => `<span class="pill">${output}</span>`).join("")}
      </div>
      <p class="small-muted">${item.routeNote}</p>
      <div class="card-actions">
        <a class="card-action" href="${item.primaryHref}">${item.primaryCta}</a>
        ${item.secondaryHref ? `<a class="github-link" href="${item.secondaryHref}">${item.secondaryCta}</a>` : ""}
      </div>
    </article>
  `).join("");
}

